package com.oms.goods.service.goods.impl;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.jdbc.core.JdbcTemplate;
import com.fasterxml.jackson.databind.ObjectMapper;
import javax.annotation.Resource;
import java.util.*;
@Service public class GoodsBundleService {
 @Resource JdbcTemplate jdbc;
 private static final ObjectMapper JSON=new ObjectMapper();
 private static void require(boolean b,String m){if(!b)throw new IllegalArgumentException(m);}
 private static long n(Object v){try{return v==null?0:new java.math.BigDecimal(v.toString()).longValueExact();}catch(Exception e){throw new IllegalArgumentException("数量或版本须为整数");}}
 private static String s(Object v){return v==null?"":v.toString();}
 private String encode(Object v){try{return JSON.writeValueAsString(v);}catch(Exception e){throw new IllegalArgumentException("套装组成无法保存");}}
 @SuppressWarnings("unchecked") private List<Map<String,Object>> rows(Object v){try{return v instanceof List?(List<Map<String,Object>>)v:JSON.readValue(s(v),List.class);}catch(Exception e){throw new IllegalArgumentException("套装组成格式无效");}}
 private Map<String,Object> parent(String c,long id){List<Map<String,Object>> rows=jdbc.queryForList("SELECT * FROM goods_sku_sn_info WHERE UPPER(company_code)=? AND id=?",c,id);require(rows.size()==1,"商品不存在或不属于当前公司");require(n(rows.get(0).get("is_package"))==1&&n(rows.get(0).get("is_fd"))==0,"请选择固定套装商品，福袋不适用");return rows.get(0);}
 public Map<String,Object> detail(String c,long id){Map<String,Object> g=parent(c,id);List<Map<String,Object>> found=jdbc.queryForList("SELECT revision,inventory_mode,enabled,components,updated_by,update_time FROM goods_bundle WHERE company_code=? AND sku_sn=?",c,g.get("sku_sn"));Map<String,Object> result=new LinkedHashMap<>();result.put("sku_sn",g.get("sku_sn"));result.put("revision",0);result.put("enabled",1);result.put("inventory_mode","VIRTUAL");result.put("components",Collections.emptyList());if(!found.isEmpty()){result.putAll(found.get(0));result.put("components",rows(result.get("components")));}return result;}
 @Transactional(rollbackFor=Exception.class) public Map<String,Object> save(String c,long id,Map<String,Object> input,String actor){
   // Same company master-data mutex as product edits; a child cannot become another kit concurrently.
   jdbc.update("INSERT IGNORE INTO goods_master_lock(company_code) VALUES (?)",c);jdbc.queryForList("SELECT company_code FROM goods_master_lock WHERE company_code=? FOR UPDATE",c);
   Map<String,Object> g=parent(c,id);String mode=s(input.getOrDefault("inventory_mode","VIRTUAL"));require(Arrays.asList("VIRTUAL","STOCKED").contains(mode),"套装库存模式无效");long enabled=n(input.get("enabled"));require(enabled==0||enabled==1,"启用开关无效");List<Map<String,Object>> lines=rows(input.get("components"));require(!lines.isEmpty()&&lines.size()<=50,"每套须有1至50种组件");Set<String> seen=new HashSet<>();List<Map<String,Object>> clean=new ArrayList<>();
   for(Map<String,Object> line:lines){String sku=s(line.get("sku_sn"));long qty=n(line.get("quantity"));require(!sku.isEmpty()&&seen.add(sku)&&!sku.equals(s(g.get("sku_sn")))&&qty>0&&qty<=100000,"组件SKU重复、自引用或数量无效");List<Map<String,Object>> children=jdbc.queryForList("SELECT goods_name,is_package,is_fd FROM goods_sku_sn_info WHERE UPPER(company_code)=? AND sku_sn=?",c,sku);require(children.size()==1&&n(children.get(0).get("is_package"))==0&&n(children.get(0).get("is_fd"))==0,"组件须为本公司唯一普通SKU，不支持嵌套套装或福袋："+sku);Map<String,Object> row=new LinkedHashMap<>();row.put("sku_sn",sku);row.put("goods_name",children.get(0).get("goods_name"));row.put("quantity",qty);clean.add(row);}
   List<Map<String,Object>> old=jdbc.queryForList("SELECT revision,inventory_mode,components FROM goods_bundle WHERE company_code=? AND sku_sn=? FOR UPDATE",c,g.get("sku_sn"));long revision=old.isEmpty()?0:n(old.get(0).get("revision"));require(revision==n(input.get("revision")),"套装组成已变化，请刷新后重试");String json=encode(clean);if(!old.isEmpty()){require(mode.equals(s(old.get(0).get("inventory_mode"))),"已发布套装不能切换库存模式，请使用新的SKU");if("STOCKED".equals(mode))require(encode(rows(old.get(0).get("components"))).equals(json),"实物套装组成发布后固定，变更配方请使用新的SKU");}
   jdbc.update("INSERT INTO goods_bundle(company_code,sku_sn,revision,inventory_mode,enabled,components,updated_by) VALUES (?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE revision=VALUES(revision),inventory_mode=VALUES(inventory_mode),enabled=VALUES(enabled),components=VALUES(components),updated_by=VALUES(updated_by)",c,g.get("sku_sn"),revision+1,mode,enabled,json,actor);
   jdbc.update("DELETE FROM goods_bundle_component WHERE company_code=? AND bundle_sku=?",c,g.get("sku_sn"));for(Map<String,Object> child:clean)jdbc.update("INSERT INTO goods_bundle_component(company_code,bundle_sku,component_sku) VALUES (?,?,?)",c,g.get("sku_sn"),child.get("sku_sn"));
   jdbc.update("INSERT INTO goods_bundle_version(company_code,sku_sn,revision,inventory_mode,enabled,components,actor) VALUES (?,?,?,?,?,?,?)",c,g.get("sku_sn"),revision+1,mode,enabled,json,actor);return detail(c,id);
 }
 public void attach(String c,List<Map<String,Object>> goods){List<String> skus=new ArrayList<>();for(Map<String,Object> row:goods)if(n(row.get("is_package"))==1)skus.add(s(row.get("sku_sn")));if(skus.isEmpty())return;List<Object> args=new ArrayList<>();args.add(c);args.addAll(skus);Map<String,Map<String,Object>> definitions=new HashMap<>();for(Map<String,Object> row:jdbc.queryForList("SELECT * FROM goods_bundle WHERE company_code=? AND sku_sn IN ("+String.join(",",Collections.nCopies(skus.size(),"?"))+")",args.toArray())){Map<String,Object> snapshot=new LinkedHashMap<>();snapshot.put("revision",row.get("revision"));snapshot.put("inventory_mode",row.get("inventory_mode"));snapshot.put("enabled",row.get("enabled"));snapshot.put("components",rows(row.get("components")));definitions.put(s(row.get("sku_sn")),snapshot);}for(Map<String,Object> g:goods)if(definitions.containsKey(s(g.get("sku_sn"))))g.put("bundle",definitions.get(s(g.get("sku_sn"))));}
}
